AND notification_id IN
#{id}

mapper.insert:
INSERT INTO notification (
    customer_id, notification_type, title, content, related_type, related_id, created_at
) VALUES (#{customerId}, #{type}, #{title}, #{content}, #{relatedType}, #{relatedId}, #{createdAt})

mapper.select:
SELECT notification_id, notification_type, title, content, read_at, created_at
FROM notification
WHERE customer_id = #{customerId}
  AND notification_type NOT IN ('COMMUNITY_COMMENT', 'KIRU_REPLY')
ORDER BY notification_id DESC
LIMIT #{limit}

